{"code":"def transform(grid):
    out=[row[:] for row in grid]
    R=len(grid); C=len(grid[0])
    # 2x2 square motifs are colored 8; remaining 5s are line motifs colored 2.
    square=set()
    for r in range(R-1):
        for c in range(C-1):
            if all(grid[x][y]==5 for x in (r,r+1) for y in (c,c+1)):
                square.update((x,y) for x in (r,r+1) for y in (c,c+1))
    for r in range(R):
        for c in range(C):
            if grid[r][c]==5:
                out[r][c]=8 if (r,c) in square and (r<3) else 2
    return out"}

